from pathlib import Path
p = Path('/home/ubuntu/lumin-candles-store/client/src/pages/Home.tsx')
s = p.read_text()
needle = '      {requestOpen && <div className="modal-backdrop"'
modal = '''      {walletSettingsOpen && <div className="modal-backdrop" onClick={() => setWalletSettingsOpen(false)}><div className="wallet-settings-modal" onClick={(event) => event.stopPropagation()}><div className="modal-top"><div><span className="section-label">محفظة نجدة</span><h2>طرق الدفع والسحب</h2></div><button onClick={() => setWalletSettingsOpen(false)} className="modal-close" aria-label="إغلاق"><X size={18} /></button></div><p className="wallet-settings-note">أضف Apple Pay أو مدى أو STC Pay للدفع إلى المحفظة. لإيداع المستحقات، أضف حسابًا بنكيًا موثقًا. لا نخزن رقم البطاقة أو IBAN الكامل.</p><div className="wallet-settings-grid"><form className="wallet-settings-form" onSubmit={(event) => { event.preventDefault(); savePaymentMethod(); }}><div className="wallet-form-heading"><CreditCard size={16} /><strong>وسيلة الدفع للمحفظة</strong></div><label>المزود<select value={paymentProvider} onChange={(event) => { const value = event.target.value as "apple_pay" | "mada" | "stc_pay" | "card"; setPaymentProvider(value); setPaymentMethodLabel(value === "apple_pay" ? "Apple Pay" : value === "mada" ? "مدى" : value === "stc_pay" ? "STC Pay" : "بطاقة بنكية"); }}><option value="apple_pay">Apple Pay</option><option value="mada">مدى</option><option value="stc_pay">STC Pay</option><option value="card">بطاقة بنكية</option></select></label><label>اسم الوسيلة<input value={paymentMethodLabel} onChange={(event) => setPaymentMethodLabel(event.target.value)} placeholder="مثال: بطاقة العمل" /></label><label>آخر ٤ أرقام (اختياري)<input inputMode="numeric" maxLength={4} value={paymentLast4} onChange={(event) => setPaymentLast4(event.target.value.replace(/\\D/g, ""))} placeholder="••••" /></label><button className="wallet-form-button" type="submit" disabled={addPaymentMethodMutation.isPending}>{addPaymentMethodMutation.isPending ? "جارٍ الحفظ..." : "حفظ وسيلة الدفع"}</button><div className="saved-wallet-items">{paymentMethodsQuery.data?.map((method) => <span key={method.id}><Check size={12} /> {method.label}{method.last4 ? ` ····${method.last4}` : ""}</span>)}</div></form><form className="wallet-settings-form" onSubmit={(event) => { event.preventDefault(); saveBankAccount(); }}><div className="wallet-form-heading"><Banknote size={16} /><strong>حساب السحب البنكي</strong></div><label>اسم البنك<input value={bankName} onChange={(event) => setBankName(event.target.value)} placeholder="مثال: البنك الراجحي" required /></label><label>اسم صاحب الحساب<input value={accountHolderName} onChange={(event) => setAccountHolderName(event.target.value)} placeholder="مطابق للهوية" required /></label><label>رقم IBAN السعودي<input dir="ltr" value={iban} onChange={(event) => setIban(event.target.value)} placeholder="SA••••••••••••••••••••••••" required /></label><button className="wallet-form-button" type="submit" disabled={addBankAccountMutation.isPending}>{addBankAccountMutation.isPending ? "جارٍ التحقق..." : "حفظ حساب السحب"}</button><div className="saved-wallet-items">{bankAccountsQuery.data?.map((account) => <span key={account.id}><Check size={12} /> {account.bankName} ····{account.ibanLast4} · {account.verificationStatus === "verified" ? "موثق" : "بانتظار التوثيق"}</span>)}</div></form></div><p className="wallet-settings-footnote"><ShieldCheck size={13} /> التحويل البنكي الفعلي وتكامل Apple Pay ومدى وSTC Pay يحتاج مفاتيح مزود الدفع وتوثيق الحساب قبل التشغيل.</p></div></div>}
'''
if needle not in s: raise SystemExit('request modal insertion point not found')
p.write_text(s.replace(needle, modal + needle, 1))
